//! DISPATCH OBSERVATION for the verified ML-DSA-65 KEYGEN core.
//!
//! Proves `dregg_pq::MlDsaKey::from_ed25519_seed` dispatches to the Lean-verified
//! `dregg_mldsa_keygen_real` core (over the `dregg-lean-ffi` archive), with ZERO hits on the
//! `fips204` crate keygen, and no opt-out. Three modes (each a FRESH process, so the
//! once-per-process `OnceLock` install is fresh):
//!   * `real`   -- install the REAL verified core; assert `from_ed25519_seed(xi26)` == NIST kg26 pk.
//!                 The process completes WITHOUT `DREGG_ALLOW_UNAUDITED_PQ`, so the crate-fallback
//!                 guard (which aborts) was never hit.
//!   * `poison` -- install a POISON core that returns the (valid) NIST kg27 keypair for ANY seed;
//!                 assert `from_ed25519_seed(xi26)` returns the POISON kg27 pk, NOT the crate's kg26
//!                 expansion of xi26 => dispatch is EXCLUSIVELY through the installed core.
//!   * `nocore` -- install nothing; `from_ed25519_seed` must ABORT (crate path is guarded).
//! Built as a `lean-lib` bin so it links the real archive.

use dregg_lean_ffi::{mldsa_keygen_real_core_available, shadow_mldsa_keygen_real};
use dregg_pq::{
    install_verified_mldsa_keygen_core_real, lean_keygen_core_real_installed, MlDsaKey,
    MlDsaKeygenCoreRealInstall,
};

const XI26_HEX: &str = "a991fd42b071d49c48ae3e75c647459e0daad1e1ba356a04801912d3294bcff8";
const KG26_PK_HEX: &str = "";
const KG27_PK_HEX: &str = "";
const KG27_REPLY: &str = " ";

fn hexdecode(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}
fn hexencode(b: &[u8]) -> String {
    const H: &[u8; 16] = b"0123456789abcdef";
    let mut o = String::with_capacity(b.len() * 2);
    for &x in b {
        o.push(H[(x >> 4) as usize] as char);
        o.push(H[(x & 15) as usize] as char);
    }
    o
}
fn xi26() -> [u8; 32] {
    let v = hexdecode(XI26_HEX);
    let mut a = [0u8; 32];
    a.copy_from_slice(&v);
    a
}

// A POISON keygen core: ignore the wire, ALWAYS return the (valid) NIST kg27 keypair.
fn poison_core(_wire: &str) -> Option<String> {
    Some(KG27_REPLY.to_string())
}

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();
    assert!(
        std::env::var("DREGG_ALLOW_UNAUDITED_PQ").is_err(),
        "observation invalid: DREGG_ALLOW_UNAUDITED_PQ is set"
    );
    match mode.as_str() {
        "real" => {
            assert!(
                mldsa_keygen_real_core_available(),
                "archive lacks dregg_mldsa_keygen_real"
            );
            let r =
                install_verified_mldsa_keygen_core_real(mldsa_keygen_real_core_available, |w| {
                    shadow_mldsa_keygen_real(w).ok()
                });
            assert_eq!(r, MlDsaKeygenCoreRealInstall::Installed, "install: {r:?}");
            assert!(lean_keygen_core_real_installed());
            let k = MlDsaKey::from_ed25519_seed(&xi26());
            let pk = hexencode(&k.public_bytes());
            assert_eq!(
                pk, KG26_PK_HEX,
                "verified core did NOT produce NIST kg26 pk"
            );
            println!("REAL-DISPATCH-OK: from_ed25519_seed(xi26) == NIST kg26 pk via the verified Lean core; crate-fallback guard never hit (no DREGG_ALLOW_UNAUDITED_PQ set).");
        }
        "poison" => {
            let r = install_verified_mldsa_keygen_core_real(|| true, poison_core);
            assert_eq!(r, MlDsaKeygenCoreRealInstall::Installed, "install: {r:?}");
            let k = MlDsaKey::from_ed25519_seed(&xi26());
            let pk = hexencode(&k.public_bytes());
            assert_eq!(
                pk, KG27_PK_HEX,
                "expected the POISON (kg27) pk from the installed core"
            );
            assert_ne!(
                pk, KG26_PK_HEX,
                "got kg26 => crate expanded xi26 (dispatch FAILED)"
            );
            println!("POISON-DISPATCH-OK: from_ed25519_seed(xi26) returned the INSTALLED core kg27 output, NOT the fips204 crate kg26 expansion => ZERO crate-keygen hits, no opt-out.");
        }
        "nocore" => {
            assert!(!lean_keygen_core_real_installed());
            // No verified core installed: the crate fallback path is GUARDED and must abort
            // (no DREGG_ALLOW_UNAUDITED_PQ). If we reach the println, the guard failed.
            let _ = MlDsaKey::from_ed25519_seed(&xi26());
            println!("NOCORE-BUG: from_ed25519_seed returned WITHOUT a verified core AND WITHOUT the abort guard!");
        }
        other => {
            eprintln!("usage: mldsa_keygen_dispatch <real|poison|nocore> (got {other:?})");
            std::process::exit(2);
        }
    }
}
